def diagnostic_settings(
    *,
    check_dependence=False,
    n_calibration=99,
    alpha=0.05,
    dependence_seed_offset=100_000,
):
    """Validate all settings that influence Pipeline.test evaluation."""
    if not isinstance(check_dependence, bool):
        raise ValueError("check_dependence must be a boolean")
    n_calibration = positive_int(n_calibration, "n_calibration")
    dependence_seed_offset = nonnegative_int(
        dependence_seed_offset, "dependence_seed_offset"
    )
    if (
        isinstance(alpha, bool)
        or not isinstance(alpha, (int, float))
        or not np.isfinite(alpha)
        or not 0 < alpha < 1
    ):
        raise ValueError("alpha must be finite and in (0, 1)")
    return {
        "check_dependence": check_dependence,
        "n_calibration": n_calibration,
        "alpha": float(alpha),
        "dependence_seed_offset": dependence_seed_offset,
    }
